package pe.com.dentalamericana.treatment;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.com.dentalamericana.security.AuthenticatedUser;import pe.com.dentalamericana.treatment.dto.TreatmentDtos.*;import java.util.List;
@RestController @RequestMapping("/api/v1")public class TreatmentController{private final TreatmentService service;public TreatmentController(TreatmentService service){this.service=service;}@GetMapping("/services")@PreAuthorize("hasAuthority('TRATAMIENTO_LEER')")public List<ServiceResponse>catalog(){return service.catalog();}@GetMapping("/treatment-plans")@PreAuthorize("hasAuthority('TRATAMIENTO_LEER')")public List<PlanResponse>list(@RequestParam(required=false)Long patientId,@RequestParam(required=false)Long encounterId){return service.list(patientId,encounterId);}@GetMapping("/treatment-plans/{id}")@PreAuthorize("hasAuthority('TRATAMIENTO_LEER')")public PlanResponse get(@PathVariable Long id){return service.get(id);}@PostMapping("/treatment-plans")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse create(@Valid@RequestBody CreatePlanRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.create(r,a,h);}@PostMapping("/treatment-plans/{id}/items")@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse item(@PathVariable Long id,@Valid@RequestBody AddItemRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.addItem(id,r,a,h);}@PatchMapping("/treatment-plans/{id}/items/{itemId}/remove")@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse remove(@PathVariable Long id,@PathVariable Long itemId,@RequestParam Long version,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.removeItem(id,itemId,version,a,h);}@PutMapping("/treatment-plans/{id}")@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse revise(@PathVariable Long id,@Valid@RequestBody RevisePlanRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.revise(id,r,a,h);}@PatchMapping("/treatment-plans/{id}/status")@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse status(@PathVariable Long id,@Valid@RequestBody ChangePlanStatusRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.status(id,r,a,h);}@PatchMapping("/treatment-plans/{id}/items/{itemId}/status")@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse itemStatus(@PathVariable Long id,@PathVariable Long itemId,@Valid@RequestBody ChangeItemStatusRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.itemStatus(id,itemId,r,a,h);}@PostMapping("/treatment-plans/{id}/items/{itemId}/evolutions")@PreAuthorize("hasAuthority('TRATAMIENTO_ESCRIBIR')")public PlanResponse evolution(@PathVariable Long id,@PathVariable Long itemId,@Valid@RequestBody EvolutionRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.evolution(id,itemId,r,a,h);}}
